// FINAL - NORMALIZE_INVOICE - WITH FIXED PAYMENT LINK - 7049869870
const raw = $input.first().json;
const body = raw.body || raw;
let parsedBody = body;
if (typeof body === 'string') {
  try { parsedBody = JSON.parse(body); } catch(e) { parsedBody = {}; }
}
const invoice = parsedBody.payload || parsedBody.invoice || parsedBody.data || parsedBody || {};

const billNo = invoice.invoice_number || invoice.number || invoice.invoice_id || parsedBody.billNo || parsedBody.bill_no;
if(!billNo) throw new Error('billNo missing: ' + JSON.stringify(Object.keys(invoice)));
const amount = Number(invoice.total || invoice.amount || parsedBody.amount || 0);
if(!amount) throw new Error('amount missing for ' + billNo);

const partyName = invoice.customer_name || invoice.contact_name || "Customer";
let partyEmail = invoice.customer_email || invoice.email || invoice.contact_persons?.[0]?.email || parsedBody.email || "";
let partyPhone = "917049869870"; // DEMO - 7049869870

const tenantId = "sikku-zoho";
const invoiceId = invoice.invoice_id || invoice.id || `ZOHO-${billNo}`;

// PAYMENT LINK FIX - NO DOUBLE SLASH
const invoiceUrl = invoice.invoice_url || invoice.url || invoice.link || "";
const baseLink = invoiceUrl || `https://books.zoho.in/app/invoices/${invoiceId}`;
const paymentLink = invoiceUrl ? invoiceUrl : `${baseLink}/payment`;

const uniqueKey = `${tenantId}_${invoiceId}_${Date.now()}_DEMO`;

return [{
  json: {
    tenantId, tenant_id: tenantId,
    billNo: String(billNo), bill_no: String(billNo),
    invoice_id: invoiceId, invoiceId: invoiceId,
    partyName, partyEmail, customer_email: partyEmail,
    partyPhone, customer_phone: partyPhone, fullPhone: partyPhone, to: partyPhone,
    amount, total: amount,
    customer_name: partyName,
    invoice_number: String(billNo),
    idempotency_key: uniqueKey, idempotencyKey: uniqueKey,
    owner_phone: "917049869870", ownerPhone: "917049869870",
    ownerName: "sikku zoho", owner_name: "sikku zoho",
    invoice_url: baseLink,
    payment_link: paymentLink,
    paymentUrl: paymentLink,
    pay_link: paymentLink,
    status: "PROCESSING",
    created_at: new Date().toISOString(),
    invoiceDate: new Date().toLocaleDateString('en-GB')
  }
}];

const o = $('NORMALIZE_INVOICE').first().json;

const raw = String(
  $input.first()?.json?.response ??
  $input.first()?.json?.text ??
  ''
).trim();

if (!raw) {
  throw new Error('AI_OUTPUT_INVALID: empty response');
}

let p;

try {
  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();

  p = JSON.parse(cleaned);
} catch {
  throw new Error('AI_OUTPUT_INVALID: invalid JSON');
}

if (
  !p ||
  typeof p.invoice_message !== 'string' ||
  typeof p.reminder_message !== 'string'
) {
  throw new Error('AI_OUTPUT_INVALID: schema');
}

const invoiceMsg = p.invoice_message.trim();
const reminderMsg = p.reminder_message.trim();

if (!invoiceMsg || !reminderMsg) {
  throw new Error('AI_OUTPUT_INVALID: empty message');
}

if (invoiceMsg.length > 2000 || reminderMsg.length > 2000) {
  throw new Error('AI_OUTPUT_INVALID: length');
}

return [{
  json: {
    ...o,
    finalInvoiceMsg: invoiceMsg,
    reminderMsg: reminderMsg,
    status: 'AI_VALIDATED'
  }
}];

// 1. जोहो से आने वाले पूरे इनपुट डेटा को निकालें
const raw = $input.first().json;

// 2. लाइव डेटा स्ट्रक्चर को सुरक्षित रूप से पार्स (Parse) करें
let d = {};
try {
  if (raw.body) {
    d = typeof raw.body === 'string' ? JSON.parse(raw.body) : raw.body;
  } else if (raw.payment) {
    d = raw.payment;
  } else {
    d = raw;
  }
} catch (e) {
  // अगर स्ट्रिंग डायरेक्ट पार्स न हो, तो ऑब्जेक्ट को मान लें
  d = raw.body || raw;
}

// अगर डेटा अभी भी किसी 'payment' की के अंदर छुपा है
if (d.payment) {
  d = d.payment;
}

// 3. इनवॉइस लिस्ट में से पहली इनवॉइस को सुरक्षित रूप से निकालें
const invoicesList = d.invoices || raw.invoices || [];
const firstInvoice = (Array.isArray(invoicesList) && invoicesList.length > 0) ? invoicesList[0] : {};

const tenantId = String(d.tenant_id ?? d.company_id ?? raw.tenant_id ?? 'sikku-zoho').trim();

// 4. बिल/इनवॉइस नंबर को ढूंढने के सभी संभावित लाइव रास्ते
const billNo = String(
    firstInvoice.invoice_number ?? 
    firstInvoice.invoice_id ?? 
    d.invoice_number ?? 
    d.invoice_id ?? 
    d.bill_no ?? 
    d.billNo ?? 
    raw.invoice_number ??
    ''
).trim();

const paymentId = String(d.payment_id ?? d.correlation_id ?? raw.payment_id ?? $execution.id).trim();
const paidAmount = Number(d.amount ?? d.total ?? d.paidAmount ?? raw.amount ?? 0);
let rawStatus = String(d.status ?? raw.status ?? 'PAID').trim().toUpperCase();

// 5. स्टेटस मैपिंग
const map = {
  'SUCCESS': 'PAID', 'COMPLETED': 'PAID', 'CREDITED': 'PAID',
  'PAID': 'PAID', 'SUCCESSFUL': 'PAID', 'PAID_SUCCESS': 'PAID'
};
const finalStatus = map[rawStatus] || 'PAID';

// 6. वैलिडेशन चेक
if (!tenantId) throw new Error('tenant_id required');
if (!billNo) throw new Error('bill_number/invoice_id required');

// 7. डुप्लीकेट रोकने का असली लॉजिक (Idempotency - लाइव में काम करेगा)
const staticData = $getWorkflowStaticData('global');
staticData.processedPayments = staticData.processedPayments || [];

if (staticData.processedPayments.includes(paymentId)) {
  throw new Error(`DUPLICATE_PAYMENT: Payment ID ${paymentId} has already been processed.`);
}
staticData.processedPayments.push(paymentId);

// 8. फाइनल आउटपुट आगे भेजें
return {
  json: {
    tenantId,
    billNo,
    paymentId,
    paidAmount,
    status: finalStatus,
    rawStatus
  }
};

const claim = $('PG_CLAIM_INVOICE').first()?.json ?? {};
if (claim.claimed !== true) return [];
return [{
  json: {
    ...$('NORMALIZE_INVOICE').first().json,
    claim_status: 'CLAIMED'
  }
}];

const row = $input.first()?.json ?? {};

if (
  row.final_status !== 'PAID' ||
  row.owner_notification_status !== 'PROCESSING' ||
  !row.owner_phone
) {
  return [];
}

return [
  {
    json: {
      ...$('VALIDATE_PAYMENT').first().json,
      idempotency_key: row.idempotency_key,
      // डेटाबेस रो से कस्टमर का असली फोन नंबर आगे पास करें
      customer_phone: row.customer_phone || $('VALIDATE_PAYMENT').first().json.customer_phone || 'N/A',
      owner_claim_status: 'CLAIMED',
      owner_notification_status: row.owner_notification_status,
    },
  },
];
